              <div className="relative">
                <textarea
                  value={prompt}
                  onChange={(e) => setPrompt(e.target.value)}
                  className="w-full h-80 bg-gray-950 border border-gray-800 rounded-lg p-6 text-sm text-gray-300 focus:ring-1 focus:ring-white focus:border-white resize-none font-sans leading-relaxed tracking-wide"
                  placeholder={mode === 'ON' ? "Analysis and Rules will appear here..." : "e.g., Place the products on the wooden table..."}
                />

                {mode === 'ON' && (
                  <button
                    onClick={handleReAnalyze}
                    disabled={isAnalyzingStyle}
                    className="absolute top-3 right-3 p-2 bg-black/80 backdrop-blur-sm border border-gray-800 rounded-lg text-gray-500 hover:text-white hover:border-white transition-all shadow-lg group"
                    title="Re-analyze images and refresh prompt"
                  >
                    <svg 
                      xmlns="http://www.w3.org/2000/svg" 
                      fill="none" 
                      viewBox="0 0 24 24" 
                      strokeWidth={1.5} 
                      stroke="currentColor" 
                      className={`w-4 h-4 ${isAnalyzingStyle ? 'animate-spin text-white' : 'group-hover:rotate-180 transition-transform duration-500'}`}
                    >
                      <path strokeLinecap="round" strokeLinejoin="round" d="M16.023 9.348h4.992v-.001M2.985 19.644v-4.992m0 0h4.992m-4.993 0 3.181 3.183a8.25 8.25 0 0 0 13.803-3.7M4.031 9.865a8.25 8.25 0 0 1 13.803-3.7l3.181 3.182m0-4.991v4.99" />
                    </svg>
                  </button>
                )}
              </div>
            </div>
          </div>

          {/* RIGHT COLUMN: Output */}
          <div className="lg:col-span-7 flex flex-col gap-6">
            <div className="bg-gray-900 border border-gray-800 rounded-2xl p-2 h-[600px] flex flex-col relative overflow-hidden group">
              <div className="absolute inset-0 bg-[url('https://grainy-gradients.vercel.app/noise.svg')] opacity-20 pointer-events-none"></div>

              {generatedImage ? (
                <div className="relative w-full h-full flex items-center justify-center bg-black rounded-xl overflow-hidden group/image">
                   <img 
                    src={generatedImage} 
                    alt="Generated Product" 
                    className="max-w-full max-h-full object-contain shadow-2xl cursor-zoom-in transition-transform duration-300 group-hover/image:scale-[1.01]"
                    onClick={() => setIsLightboxOpen(true)}
                  />
                  <a 
                    href={generatedImage} 
                    download="nanostudio-edit.png"
                    className="absolute top-4 right-4 bg-white text-black hover:bg-gray-200 px-4 py-2 rounded-full text-sm font-medium transition-colors border border-black flex items-center gap-2 z-10"
                    onClick={(e) => e.stopPropagation()}
                  >
                    <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={1.5} stroke="currentColor" className="w-4 h-4">
                      <path strokeLinecap="round" strokeLinejoin="round" d="M3 16.5v2.25A2.25 2.25 0 0 0 5.25 21h13.5A2.25 2.25 0 0 0 21 18.75V16.5M12 9.75v10.5m0 0L7.5 15.75M12 20.25l4.5-4.5M12 3v9" />
                    </svg>
                    Download
                  </a>
                  <div className="absolute bottom-4 left-1/2 -translate-x-1/2 opacity-0 group-hover/image:opacity-100 transition-opacity bg-black/50 backdrop-blur-md px-3 py-1 rounded-full text-xs text-white/80 pointer-events-none border border-white/20">
                    Click to enlarge
                  </div>
                </div>
              ) : (
                <div className="w-full h-full flex flex-col items-center justify-center text-gray-500 gap-4 bg-gray-950 rounded-xl">
                  {isGenerating ? (
                    <div className="flex flex-col items-center gap-4 animate-pulse">
                      <div className="w-16 h-16 rounded-full bg-gray-800"></div>
                      <div className="h-4 w-32 bg-gray-800 rounded"></div>
                    </div>
                  ) : (
                    <>
                      <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={1} stroke="currentColor" className="w-24 h-24 opacity-20">
                        <path strokeLinecap="round" strokeLinejoin="round" d="m2.25 15.75 5.159-5.159a2.25 2.25 0 0 1 3.182 0l5.159 5.159m-1.5-1.5 1.409-1.409a2.25 2.25 0 0 1 3.182 0l2.909 2.909m-18 3.75h16.5a1.5 1.5 0 0 0 1.5-1.5V6a1.5 1.5 0 0 0-1.5-1.5H3.75A1.5 1.5 0 0 0 2.25 6v12a1.5 1.5 0 0 0 1.5 1.5Zm10.5-11.25h.008v.008h-.008V8.25Zm.375 0a.375.375 0 1 1-.75 0 .375.375 0 0 1 .75 0Z" />
                      </svg>
                      <p className="text-gray-500">Result will appear here</p>
                    </>
                  )}
                </div>
              )}
            </div>

            {/* Action Button Moved Here */}
            <button
              onClick={handleGenerate}
              disabled={isButtonDisabled}
              className={`
                w-full py-4 px-6 rounded-xl font-bold text-lg transition-all duration-300 transform active:scale-[0.98]
                flex items-center justify-center gap-3 border
                ${isButtonDisabled
                  ? 'bg-gray-900 border-gray-800 text-gray-500 cursor-not-allowed' 
                  : 'bg-white border-white text-black hover:bg-black hover:text-white'
                }
              `}
            >
              {isGenerating ? (
                <>
                  <svg className="animate-spin -ml-1 mr-3 h-5 w-5" xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24">
                    <circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4"></circle>
                    <path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"></path>
                  </svg>
                  Processing...
                </>
              ) : isAnalyzingStyle ? (
                 <>
                  <svg className="animate-spin -ml-1 mr-3 h-5 w-5" xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24">
                    <circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4"></circle>
                    <path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"></path>
                  </svg>
                  Analyzing Style...
                </>
              ) : (
                <>
                  <svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24" fill="currentColor" className="w-5 h-5">
                    <path fillRule="evenodd" d="M9.315 7.584C12.195 3.883 16.695 1.5 21.75 1.5a.75.75 0 0 1 .75.75c0 5.056-2.383 9.555-6.084 12.436h.001c-3.3 2.567-6.93 2.567-9.691 2.567H3.25C1.83 17.253.375 18.064.375 20.25a.75.75 0 0 0 .75.75h21.75a.75.75 0 0 0 .75-.75c0-2.186-1.455-2.997-2.875-2.997H16.19c-2.76 0-6.39 0-9.69-2.567C2.882 11.952.5 7.452.5 2.396a.75.75 0 0 1 .75-.75c5.055 0 9.555 2.383 12.436 6.084l-3.375 3.375-3.001-3.52Z" clipRule="evenodd" />
                  </svg>
                  Generate Image
                </>
              )}
            </button>
            {error && (
              <div className="p-4 bg-gray-900 border border-white text-white rounded-lg text-sm">
                {error}
              </div>
            )}

            {/* History Section */}
            {history.length > 0 && (
              <div className="bg-gray-900 border border-gray-800 rounded-2xl p-6">
                <div className="flex items-center justify-between mb-4">
                  <h3 className="text-sm font-semibold text-gray-500 uppercase tracking-wider">Recent Generations</h3>
                  <button 
                    onClick={() => setHistory([])}
                    className="text-xs text-gray-500 hover:text-white transition-colors"
                  >
                    Clear History
                  </button>
                </div>
                <div className="flex gap-4 overflow-x-auto pb-2 scrollbar-thin scrollbar-thumb-gray-800 scrollbar-track-transparent">
                  {history.map(item => (
                    <button
                      key={item.id}
                      onClick={() => setGeneratedImage(item.imageUrl)}
                      className={`relative flex-shrink-0 w-24 h-24 rounded-lg overflow-hidden border-2 transition-all group ${
                        generatedImage === item.imageUrl 
                          ? 'border-white ring-2 ring-white/20' 
                          : 'border-transparent hover:border-gray-600'
                      }`}
                    >
                      <img 
                        src={item.imageUrl} 
                        alt="History item" 
                        className="w-full h-full object-cover" 
                      />
                      <div className="absolute inset-0 bg-black/0 group-hover:bg-black/10 transition-colors" />
                    </button>
                  ))}
                </div>
              </div>
            )}
          </div>
        </div>
      </main>

      {/* Lightbox Overlay */}
      {isLightboxOpen && generatedImage && (
        <div 
          className="fixed inset-0 z-[100] flex items-center justify-center bg-black/95 backdrop-blur-md p-4 animate-in fade-in duration-200"
          onClick={() => setIsLightboxOpen(false)}
        >
          {/* Close Button */}
          <button 
            className="absolute top-6 right-6 text-gray-400 hover:text-white transition-colors bg-gray-900 rounded-full p-2 hover:bg-gray-800 border border-gray-800 z-50"
            onClick={(e) => {
              e.stopPropagation();
              setIsLightboxOpen(false);
            }}
          >
            <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={1.5} stroke="currentColor" className="w-8 h-8">
              <path strokeLinecap="round" strokeLinejoin="round" d="M6 18L18 6M6 6l12 12" />
            </svg>
          </button>

          <img 
            src={generatedImage} 
            alt="Full Resolution Result" 
            className="max-w-full max-h-full object-contain shadow-2xl rounded-sm border border-gray-800"
            onClick={(e) => e.stopPropagation()}
          />
        </div>
      )}
    </div>
  );
};

export default App;

import React, { useState, useEffect, useCallback } from 'react';
import { ImageUpload } from './components/ImageUpload';
import { Controls } from './components/Controls';
import { AspectRatio, LightingStyle, CameraPerspective, HistoryItem, UploadedImage } from './types';
import { analyzeStyleReference, generateEditedImage, fileToBase64 } from './services/geminiService';

const App: React.FC = () => {
  // Mode State: ON = Auto/Creative, OFF = Manual/Scene Preservation
  const [mode, setMode] = useState<'ON' | 'OFF'>('ON');

  // State for Inputs (Arrays)
  const [productImages, setProductImages] = useState<UploadedImage[]>([]);
  const [styleImages, setStyleImages] = useState<UploadedImage[]>([]);

  const [styleDescription, setStyleDescription] = useState<string>("");
  const [isAnalyzingStyle, setIsAnalyzingStyle] = useState<boolean>(false);

  // State for Controls - Defaulting to AUTO
  const [aspectRatio, setAspectRatio] = useState<AspectRatio>(AspectRatio.AUTO);
  const [lighting, setLighting] = useState<LightingStyle>(LightingStyle.AUTO);
  const [perspective, setPerspective] = useState<CameraPerspective>(CameraPerspective.AUTO);

  // State for Custom Inferred Values (when Auto is selected but analysis finds a custom value)
  const [inferredLighting, setInferredLighting] = useState<string | null>(null);
  const [inferredPerspective, setInferredPerspective] = useState<string | null>(null);

  // State for Prompt
  const [prompt, setPrompt] = useState<string>("");

  // State for Generation
  const [isGenerating, setIsGenerating] = useState<boolean>(false);
  const [generatedImage, setGeneratedImage] = useState<string | null>(null);
  const [error, setError] = useState<string | null>(null);

  // State for Lightbox
  const [isLightboxOpen, setIsLightboxOpen] = useState<boolean>(false);

  // State for Download Menu
  const [isDownloadMenuOpen, setIsDownloadMenuOpen] = useState<boolean>(false);

  // State for History
  const [history, setHistory] = useState<HistoryItem[]>([]);

  // Update prompt whenever controls or style description changes (ONLY IN ON MODE)
  useEffect(() => {
    if (mode === 'OFF') return;

    // 1. Analysis Section
    let analysisSection = "";
    if (styleDescription) {
      // Build string for inferred values if they exist
      const inferredLightText = inferredLighting ? `Inferred Lighting: ${inferredLighting}` : "";
      const inferredCamText = inferredPerspective ? `Inferred Angle:    ${inferredPerspective}` : "";
      const inferenceDetails = [inferredLightText, inferredCamText].filter(Boolean).join('\n');

      analysisSection = `[ STYLE ANALYSIS & INFERENCE ]
----------------------------------------------------------------------
${styleDescription}
${inferenceDetails ? `\n${inferenceDetails}\n` : ''}
`;
    }

    // Determine values to show in prompt (Fallbacks if AUTO is still selected for some reason)
    const activeLighting = lighting === LightingStyle.AUTO 
      ? (inferredLighting ? `${inferredLighting} (Inferred)` : "Studio Lighting (Default)")
      : lighting;

    const activePerspective = perspective === CameraPerspective.AUTO 
      ? (inferredPerspective ? `${inferredPerspective} (Inferred)` : "Eye Level (Default)")
      : perspective;

    const activeAspectRatio = aspectRatio === AspectRatio.AUTO ? "1:1" : aspectRatio;

    // 2. The Fixed Base Prompt with Dynamic Values
    const baseRules = `[ SYSTEM OPERATIONAL FOUNDATION ]
----------------------------------------------------------------------
Rely on the following rules and instructions as a core internal operational foundation of the tool.

[ REFERENCE PROCESSING MODE: PROFESSIONAL REFINEMENT & ENHANCEMENT ]
----------------------------------------------------------------------
• CORE OBJECTIVE: Deeply analyze the Reference Image (concept, composition, lighting, colors, perspective).
• EXECUTION LOGIC: Refine, enhance, and professionally develop the reference’s core concept.
• NO DRIFT RULE: Do NOT drift away from the reference’s original core idea. The result must remain clearly connected to the reference.
• GENERATION GOAL: Deliver a higher-quality, more professional execution of the reference. Do not replace the concept; elevate it.
• VISUAL FIDELITY: Preserve the main composition structure and mood, but upgrade the lighting, texture, and clarity to a commercial standard.

[ TECHNICAL CONFIGURATION ]
----------------------------------------------------------------------
Lighting Style:   ${activeLighting}
Camera Angle:     ${activePerspective}
Aspect Ratio:     ${activeAspectRatio}

[ CORE VISUAL DIRECTIVES ]
----------------------------------------------------------------------
• Generate a photorealistic, high-end product photograph.
• Subject: The product is featured in the provided image. Keep it completely unaltered.
• Style: Clean, modern, and professional.

[ PEOPLE & CHARACTER HANDLING ]
----------------------------------------------------------------------
• ALLOW PEOPLE: The presence of people in product or reference images is permitted.
• CHARACTER REFINEMENT: If the reference contains a person, you may generate a new character that fits the SAME vibe and role, or keep the composition similar.
• IDENTITY: Do not strictly copy specific facial features (privacy), but match the demographic, styling, and pose energy of the reference.

[ COMPOSITION & ENVIRONMENT ]
----------------------------------------------------------------------
• CRITICAL: Preserve the final output dimensions with NO empty white areas.
• Extend the scene naturally to fill the ENTIRE frame.
• There must be ZERO white space, borders, or padding in the final result.
• Seamlessly integrate all subjects into this full-bleed environment.

[ STRICT NEGATIVE CONSTRAINTS ]
----------------------------------------------------------------------
• STRICT REQUIREMENT: The final generated image must be completely free of text, writing, logos, symbols, and watermarks.
• TEXT BAN: Ensure NO letters, NO characters, and NO written language appear anywhere in the scene. Even if the style reference contains text, IGNORE IT.

[ SUBJECT INTEGRITY & RULES ]
----------------------------------------------------------------------
• COUNT RULE: Use ONLY the ${productImages.length} uploaded product(s). IGNORE the number of products shown in the style reference images.
• PACKAGING PRESERVATION: Treat each product image as a fixed visual object. Keep every product’s packaging design exactly as it is.
• TRUE COLOR PRESERVATION: Do NOT change or replace the product’s original body color.
• MULTI-PRODUCT INDEPENDENCE: When multiple products are uploaded, keep each product’s original color exactly as it is.

[ CREATIVE EXECUTION ]
----------------------------------------------------------------------
• COLOR & MOOD: Use the style reference to strictly guide the color mood and grading.
• ENHANCEMENT: Improve lighting and reflections to look more expensive and premium.
• COMPOSITION: You may optimize the product placement for better balance, but keep the overall scene logic consistent with the reference.`;

    // Combine them
    setPrompt(`${analysisSection}${baseRules}`);

  }, [lighting, perspective, aspectRatio, productImages.length, styleDescription, mode, inferredLighting, inferredPerspective]);

  // When Mode switches to OFF, clear the auto-generated prompt if user hasn't typed
  useEffect(() => {
    if (mode === 'OFF') {
      setPrompt("");
    } else {
      // Trigger prompt regeneration by touching state
      setPerspective(prev => prev); 
      // If we have any images but controls are AUTO, triggering analysis might be good
      // ONLY analyze if no description exists (Lock)
      if ((styleImages.length > 0 || productImages.length > 0) && !styleDescription) {
        // Decide what to analyze based on priority
        const imagesToAnalyze = styleImages.length > 0 ? styleImages : productImages;
        analyzeStyles(imagesToAnalyze);
      }
    }
  }, [mode]);

  // Helper to extract clean base64s from UploadedImage array
  const getCleanBase64s = (images: UploadedImage[]) => {
    return images.map(img => img.base64.split(',')[1]);
  };

  const analyzeStyles = async (images: UploadedImage[]) => {
    if (images.length === 0) return;

    setIsAnalyzingStyle(true);
    try {
      const base64s = getCleanBase64s(images);
      const result = await analyzeStyleReference(base64s);

      setStyleDescription(result.description);

      // ASPECT RATIO
      // Use existing Enum mapping for aspect ratio as it's a technical setting
      setAspectRatio((current) => current === AspectRatio.AUTO ? result.recommendedAspectRatio as AspectRatio : current);

      // LIGHTING
      // If currently Auto, try to map to enum OR use custom inferred string
      if (lighting === LightingStyle.AUTO) {
        const lightingValues = Object.values(LightingStyle) as string[];
        if (lightingValues.includes(result.recommendedLighting)) {
          // Exact match found in Enums
          setLighting(result.recommendedLighting as LightingStyle);
          setInferredLighting(null);
        } else {
          // No match, it's a custom description
          setInferredLighting(result.recommendedLighting);
          // Keep state as Auto so dropdown shows "Auto"
        }
      }

      // PERSPECTIVE
      // If currently Auto, try to map to enum OR use custom inferred string
      if (perspective === CameraPerspective.AUTO) {
        const perspectiveValues = Object.values(CameraPerspective) as string[];
        if (perspectiveValues.includes(result.recommendedPerspective)) {
          // Exact match found in Enums
          setPerspective(result.recommendedPerspective as CameraPerspective);
          setInferredPerspective(null);
        } else {
          // No match, it's a custom description
          setInferredPerspective(result.recommendedPerspective);
          // Keep state as Auto so dropdown shows "Auto"
        }
      }

    } catch (err) {
      console.error(err);
      setError("Failed to analyze style reference images.");
    } finally {
      setIsAnalyzingStyle(false);
    }
  };

  const handleReAnalyze = () => {
    if (mode === 'OFF' || isAnalyzingStyle) return;

    // Explicit refresh action - this bypasses the lock
    // Determine what to analyze based on current uploads
    // Prioritize style images if present, otherwise analyze product images
    const imagesToAnalyze = styleImages.length > 0 ? styleImages : productImages;

    if (imagesToAnalyze.length > 0) {
      analyzeStyles(imagesToAnalyze);
    } else {
      setStyleDescription("");
    }
  };

  // Handle Style Image Updates
  const handleStyleImagesAdded = (newImages: UploadedImage[]) => {
    const updated = [...styleImages, ...newImages];
    setStyleImages(updated);

    // Automatic analysis upon upload (when in ON mode)
    if (mode === 'ON') {
      // Prioritize style images for analysis and start immediately
      analyzeStyles(updated);
    } else if (mode === 'OFF') {
      setStyleDescription("");
    }
  };

  const handleStyleImageRemoved = (id: string) => {
    const updated = styleImages.filter(img => img.id !== id);
    setStyleImages(updated);

    // STRICT LOCK: Do not re-analyze or clear description automatically in ON mode
    if (mode === 'OFF' && updated.length === 0) {
      setStyleDescription("");
    }
  };

  // Handle Product Image Updates
  const handleProductImagesAdded = (newImages: UploadedImage[]) => {
    const updated = [...productImages, ...newImages];
    setProductImages(updated);
    // Reset generation when new product uploaded
    setGeneratedImage(null);
    setIsDownloadMenuOpen(false);

    // If in ON mode, no style images, AND no existing analysis
    if (mode === 'ON' && styleImages.length === 0 && !styleDescription) {
        analyzeStyles(updated);
    }
  };

  const handleProductImageRemoved = (id: string) => {
    const updated = productImages.filter(img => img.id !== id);
    setProductImages(updated);
    // Strict Lock applies here too - do not modify analysis automatically
  };

  const handleGenerate = async () => {
    if (productImages.length === 0) {
      setError("Please upload at least one product image.");
      return;
    }

    setIsGenerating(true);
    setError(null);
    setGeneratedImage(null);
    setIsDownloadMenuOpen(false);

    try {
      const productBase64s = getCleanBase64s(productImages);
      let referenceBase64s: string[] = [];
      let finalPrompt = prompt;

      if (mode === 'OFF') {
        // SCENE PRESERVATION MODE
        // We pass styleImages as reference scenes
        if (styleImages.length > 0) {
          referenceBase64s = getCleanBase64s(styleImages);

          if (!finalPrompt.trim()) {
            finalPrompt = "Seamlessly insert the product image(s) into the scene image(s). Preserve the scene's lighting, perspective, and background details accurately. Replace any existing subject in the scene with the new product.";
          }
        } else if (!finalPrompt.trim()) {
           setError("In Manual mode, please provide a prompt or a scene reference image.");
           setIsGenerating(false);
           return;
        }
      } else {
        // ON MODE (Creative)
        if (!finalPrompt) {
          setError("Generating prompt...");
          return;
        }
      }

      // If Auto is still selected (e.g. analysis failed or wasn't triggered), use defaults for the API call
      // The prompt text will already have "Default" text from useEffect, but we need valid strings for imageConfig
      const effectiveAspectRatio = aspectRatio === AspectRatio.AUTO ? "1:1" : aspectRatio;

      // We now pass the full prompt (which includes rules) to the service
      const resultImageUrl = await generateEditedImage(
        productBase64s, 
        finalPrompt, 
        effectiveAspectRatio, 
        referenceBase64s
      );

      setGeneratedImage(resultImageUrl);

      // Add to history
      setHistory(prev => [
        {
          id: Date.now().toString(),
          imageUrl: resultImageUrl,
          timestamp: Date.now()
        },
        ...prev
      ]);

    } catch (err) {
      console.error(err);
      setError("Failed to generate image. Please try again.");
    } finally {
      setIsGenerating(false);
    }
  };

  const downloadImage = (format: 'png' | 'jpg') => {
    if (!generatedImage) return;
    const filename = `freebird-edit-${Date.now()}`;

    if (format === 'png') {
      const link = document.createElement('a');
      link.href = generatedImage;
      link.download = `${filename}.png`;
      document.body.appendChild(link);
      link.click();
      document.body.removeChild(link);
    } else {
      const img = new Image();
      img.src = generatedImage;
      img.onload = () => {
        const canvas = document.createElement('canvas');
        canvas.width = img.width;
        canvas.height = img.height;
        const ctx = canvas.getContext('2d');
        if (ctx) {
          ctx.fillStyle = '#FFFFFF';
          ctx.fillRect(0, 0, canvas.width, canvas.height);
          ctx.drawImage(img, 0, 0);
          const link = document.createElement('a');
          link.href = canvas.toDataURL('image/jpeg', 0.92);
          link.download = `${filename}.jpg`;
          document.body.appendChild(link);
          link.click();
          document.body.removeChild(link);
        }
      };
    }
    setIsDownloadMenuOpen(false);
  };

  // Prevent scrolling when lightbox is open
  useEffect(() => {
    if (isLightboxOpen) {
      document.body.style.overflow = 'hidden';
    } else {
      document.body.style.overflow = 'unset';
    }
    return () => {
      document.body.style.overflow = 'unset';
    };
  }, [isLightboxOpen]);

  // Determine button disabled state logic
  const isButtonDisabled = productImages.length === 0 || isGenerating || isAnalyzingStyle || (mode === 'ON' && !styleDescription);

  return (
    <div className="min-h-screen bg-gray-950 text-gray-100 font-sans selection:bg-white selection:text-black">
      {/* Header */}
      <header className="border-b border-gray-800 bg-gray-950 sticky top-0 z-50">
        <div className="w-full py-4 flex flex-col items-center justify-center">
          <h1 className="text-3xl font-bold text-white tracking-tight mb-1">
            FreeBirdTool
          </h1>
          <span className="text-[10px] text-gray-500 font-medium tracking-wide">
            By the grace of Allah, I was blessed to create this tool.
          </span>
        </div>
      </header>

      <main className="max-w-7xl mx-auto px-4 py-8">
        <div className="grid grid-cols-1 lg:grid-cols-12 gap-8">

          {/* LEFT COLUMN: Controls & Inputs */}
          <div className="lg:col-span-5 flex flex-col gap-8">

            {/* Step 1: Uploads */}
            <div className="space-y-6 bg-gray-900 p-6 rounded-2xl border border-gray-800">
              <h2 className="text-lg font-semibold flex items-center gap-2 text-white">
                <span className="w-6 h-6 rounded-full bg-gray-800 text-gray-500 text-xs flex items-center justify-center border border-gray-700">1</span>
                Upload Assets
              </h2>

              <ImageUpload 
                label="Product Images (Subjects)" 
                images={productImages}
                onImagesAdded={handleProductImagesAdded}
                onImageRemoved={handleProductImageRemoved}
                heightClass="h-56"
                placeholderText="Upload product shots"
              />

              <div className="pt-2 border-t border-gray-800">
                <div className="flex justify-between items-center mb-2">
                  <label className="text-sm font-medium text-gray-300">
                    {mode === 'ON' ? 'Style References (Optional)' : 'Scene Backgrounds (Optional)'}
                  </label>
                  <div className="flex items-center gap-2">
                     {isAnalyzingStyle && mode === 'ON' && <span className="text-xs text-white animate-pulse">Analyzing...</span>}
                     {mode === 'ON' && !isAnalyzingStyle && (styleImages.length > 0 || (styleImages.length === 0 && productImages.length > 0)) && (
                       <button
                         onClick={handleReAnalyze}
                         className="text-xs flex items-center gap-1 text-gray-500 hover:text-white transition-colors border border-transparent hover:border-gray-700 px-2 py-0.5 rounded-md"
                         title="Re-analyze Images"
                       >
                         <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={1.5} stroke="currentColor" className="w-3.5 h-3.5">
                           <path strokeLinecap="round" strokeLinejoin="round" d="M16.023 9.348h4.992v-.001M2.985 19.644v-4.992m0 0h4.992m-4.993 0 3.181 3.183a8.25 8.25 0 0 0 13.803-3.7M4.031 9.865a8.25 8.25 0 0 1 13.803-3.7l3.181 3.182m0-4.991v4.99" />
                         </svg>
                         Re-analyze
                       </button>
                     )}
                   </div>
                </div>
                <ImageUpload 
                  label=""
                  images={styleImages}
                  onImagesAdded={handleStyleImagesAdded}
                  onImageRemoved={handleStyleImageRemoved}
                  placeholderText={mode === 'ON' ? "Upload vibes" : "Upload scenes"}
                  heightClass="h-24"
                />
              </div>
            </div>

            {/* Step 2: Settings */}
            <div className="space-y-6 bg-gray-900 p-6 rounded-2xl border border-gray-800">
              <h2 className="text-lg font-semibold flex items-center gap-2 text-white">
                 <span className="w-6 h-6 rounded-full bg-gray-800 text-gray-500 text-xs flex items-center justify-center border border-gray-700">2</span>
                Configuration
              </h2>
              <Controls 
                aspectRatio={aspectRatio} setAspectRatio={setAspectRatio}
                lighting={lighting} setLighting={setLighting}
                perspective={perspective} setPerspective={setPerspective}
                mode={mode} setMode={setMode}
              />
            </div>

            {/* Step 3: Prompt */}
            <div className="space-y-4 bg-gray-900 p-6 rounded-2xl border border-gray-800">
              <h2 className="text-lg font-semibold flex items-center gap-2 text-white">
                 <span className="w-6 h-6 rounded-full bg-gray-800 text-gray-500 text-xs flex items-center justify-center border border-gray-700">3</span>
                {mode === 'ON' ? 'Generated Prompt & Rules' : 'Manual Prompt'}
              </h2>
              <p className="text-xs text-gray-500">
                {mode === 'ON' 
                  ? "This is the single source of truth for generation, including analysis and strict foundation rules."
                  : "Enter instructions for the scene replacement, or leave empty for auto-composition."
                }
              </p>

              <div className="relative">
                <textarea
                  value={prompt}
                  onChange={(e) => setPrompt(e.target.value)}
                  className="w-full h-80 bg-gray-950 border border-gray-800 rounded-lg p-6 text-sm text-gray-300 focus:ring-1 focus:ring-white focus:border-white resize-none font-sans leading-relaxed tracking-wide"
                  placeholder={mode === 'ON' ? "Analysis and Rules will appear here..." : "e.g., Place the products on the wooden table..."}
                />

                {mode === 'ON' && (
                  <button
                    onClick={handleReAnalyze}
                    disabled={isAnalyzingStyle}
                    className="absolute top-3 right-3 p-2 bg-black/80 backdrop-blur-sm border border-gray-800 rounded-lg text-gray-500 hover:text-white hover:border-white transition-all shadow-lg group"
                    title="Re-analyze images and refresh prompt"
                  >
                    <svg 
                      xmlns="http://www.w3.org/2000/svg" 
                      fill="none" 
                      viewBox="0 0 24 24" 
                      strokeWidth={1.5} 
                      stroke="currentColor" 
                      className={`w-4 h-4 ${isAnalyzingStyle ? 'animate-spin text-white' : 'group-hover:rotate-180 transition-transform duration-500'}`}
                    >
                      <path strokeLinecap="round" strokeLinejoin="round" d="M16.023 9.348h4.992v-.001M2.985 19.644v-4.992m0 0h4.992m-4.993 0 3.181 3.183a8.25 8.25 0 0 0 13.803-3.7M4.031 9.865a8.25 8.25 0 0 1 13.803-3.7l3.181 3.182m0-4.991v4.99" />
                    </svg>
                  </button>
                )}
              </div>
            </div>
          </div>

          {/* RIGHT COLUMN: Output */}
          <div className="lg:col-span-7 flex flex-col gap-6">
            <div className="bg-gray-900 border border-gray-800 rounded-2xl p-2 h-[600px] flex flex-col relative overflow-hidden group">
              <div className="absolute inset-0 bg-[url('https://grainy-gradients.vercel.app/noise.svg')] opacity-20 pointer-events-none"></div>

              {generatedImage ? (
                <div className="relative w-full h-full flex items-center justify-center bg-black rounded-xl overflow-hidden group/image">
                   <img 
                    src={generatedImage} 
                    alt="Generated Product" 
                    className="max-w-full max-h-full object-contain shadow-2xl cursor-zoom-in transition-transform duration-300 group-hover/image:scale-[1.01]"
                    onClick={() => setIsLightboxOpen(true)}
                  />
                  <div className="absolute bottom-4 left-1/2 -translate-x-1/2 opacity-0 group-hover/image:opacity-100 transition-opacity bg-black/50 backdrop-blur-md px-3 py-1 rounded-full text-xs text-white/80 pointer-events-none border border-white/20">
                    Click to enlarge
                  </div>
                </div>
              ) : (
                <div className="w-full h-full flex flex-col items-center justify-center text-gray-500 gap-4 bg-gray-950 rounded-xl">
                  {isGenerating ? (
                    <div className="flex flex-col items-center gap-4 animate-pulse">
                      <div className="w-16 h-16 rounded-full bg-gray-800"></div>
                      <div className="h-4 w-32 bg-gray-800 rounded"></div>
                    </div>
                  ) : (
                    <>
                      <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={1} stroke="currentColor" className="w-24 h-24 opacity-20">
                        <path strokeLinecap="round" strokeLinejoin="round" d="m2.25 15.75 5.159-5.159a2.25 2.25 0 0 1 3.182 0l5.159 5.159m-1.5-1.5 1.409-1.409a2.25 2.25 0 0 1 3.182 0l2.909 2.909m-18 3.75h16.5a1.5 1.5 0 0 0 1.5-1.5V6a1.5 1.5 0 0 0-1.5-1.5H3.75A1.5 1.5 0 0 0 2.25 6v12a1.5 1.5 0 0 0 1.5 1.5Zm10.5-11.25h.008v.008h-.008V8.25Zm.375 0a.375.375 0 1 1-.75 0 .375.375 0 0 1 .75 0Z" />
                      </svg>
                      <p className="text-gray-500">Result will appear here</p>
                    </>
                  )}
                </div>
              )}
            </div>

            {/* Dedicated Download Button Area */}
            {generatedImage && (
              <div className="relative z-20">
                <button 
                  onClick={() => setIsDownloadMenuOpen(!isDownloadMenuOpen)}
                  className="w-full bg-gray-800 hover:bg-gray-700 text-white font-medium py-3 px-4 rounded-xl transition-colors flex items-center justify-center gap-2 border border-gray-700"
                >
                  <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={1.5} stroke="currentColor" className="w-5 h-5">
                    <path strokeLinecap="round" strokeLinejoin="round" d="M3 16.5v2.25A2.25 2.25 0 0 0 5.25 21h13.5A2.25 2.25 0 0 0 21 18.75V16.5M12 9.75v10.5m0 0L7.5 15.75M12 20.25l4.5-4.5M12 3v9" />
                  </svg>
                  Download Result
                  <svg 
                    xmlns="http://www.w3.org/2000/svg" 
                    fill="none" 
                    viewBox="0 0 24 24" 
                    strokeWidth={1.5} 
                    stroke="currentColor" 
                    className={`w-4 h-4 transition-transform duration-200 ${isDownloadMenuOpen ? 'rotate-180' : ''}`}
                  >
                    <path strokeLinecap="round" strokeLinejoin="round" d="m19.5 8.25-7.5 7.5-7.5-7.5" />
                  </svg>
                </button>

                {isDownloadMenuOpen && (
                  <div className="absolute top-full left-0 right-0 mt-2 bg-gray-900 border border-gray-800 rounded-xl shadow-2xl overflow-hidden flex flex-col p-1 z-30 animate-in fade-in zoom-in-95 duration-150">
                    <button 
                      onClick={() => downloadImage('png')}
                      className="flex items-center justify-between px-4 py-3 text-sm text-gray-300 hover:text-white hover:bg-gray-800 rounded-lg transition-colors"
                    >
                      <span className="font-medium">Download PNG 2K</span>
                      <span className="text-xs text-gray-500 bg-gray-800 px-2 py-0.5 rounded border border-gray-700">HQ</span>
                    </button>
                    <button 
                      onClick={() => downloadImage('jpg')}
                      className="flex items-center justify-between px-4 py-3 text-sm text-gray-300 hover:text-white hover:bg-gray-800 rounded-lg transition-colors"
                    >
                      <span className="font-medium">Download JPG 2K</span>
                      <span className="text-xs text-gray-500 bg-gray-800 px-2 py-0.5 rounded border border-gray-700">Compressed</span>
                    </button>
                  </div>
                )}
              </div>
            )}

            {/* Action Button */}
            <button
              onClick={handleGenerate}
              disabled={isButtonDisabled}
              className={`
                w-full py-4 px-6 rounded-xl font-bold text-lg transition-all duration-300 transform active:scale-[0.98]
                flex items-center justify-center gap-3 border
                ${isButtonDisabled
                  ? 'bg-gray-900 border-gray-800 text-gray-500 cursor-not-allowed' 
                  : 'bg-white border-white text-black hover:bg-black hover:text-white'
                }
              `}
            >
              {isGenerating ? (
                <>
                  <svg className="animate-spin -ml-1 mr-3 h-5 w-5" xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24">
                    <circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4"></circle>
                    <path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"></path>
                  </svg>
                  Processing...
                </>
              ) : isAnalyzingStyle ? (
                 <>
                  <svg className="animate-spin -ml-1 mr-3 h-5 w-5" xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24">
                    <circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4"></circle>
                    <path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"></path>
                  </svg>
                  Analyzing Style...
                </>
              ) : (
                <>
                  <svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24" fill="currentColor" className="w-5 h-5">
                    <path fillRule="evenodd" d="M9.315 7.584C12.195 3.883 16.695 1.5 21.75 1.5a.75.75 0 0 1 .75.75c0 5.056-2.383 9.555-6.084 12.436h.001c-3.3 2.567-6.93 2.567-9.691 2.567H3.25C1.83 17.253.375 18.064.375 20.25a.75.75 0 0 0 .75.75h21.75a.75.75 0 0 0 .75-.75c0-2.186-1.455-2.997-2.875-2.997H16.19c-2.76 0-6.39 0-9.69-2.567C2.882 11.952.5 7.452.5 2.396a.75.75 0 0 1 .75-.75c5.055 0 9.555 2.383 12.436 6.084l-3.375 3.375-3.001-3.52Z" clipRule="evenodd" />
                  </svg>
                  Generate Image
                </>
              )}
            </button>
            {error && (
              <div className="p-4 bg-gray-900 border border-white text-white rounded-lg text-sm">
                {error}
              </div>
            )}

            {/* History Section */}
            {history.length > 0 && (
              <div className="bg-gray-900 border border-gray-800 rounded-2xl p-6">
                <div className="flex items-center justify-between mb-4">
                  <h3 className="text-sm font-semibold text-gray-500 uppercase tracking-wider">Recent Generations</h3>
                  <button 
                    onClick={() => setHistory([])}
                    className="text-xs text-gray-500 hover:text-white transition-colors"
                  >
                    Clear History
                  </button>
                </div>
                <div className="flex gap-4 overflow-x-auto pb-2 scrollbar-thin scrollbar-thumb-gray-800 scrollbar-track-transparent">
                  {history.map(item => (
                    <button
                      key={item.id}
                      onClick={() => setGeneratedImage(item.imageUrl)}
                      className={`relative flex-shrink-0 w-24 h-24 rounded-lg overflow-hidden border-2 transition-all group ${
                        generatedImage === item.imageUrl 
                          ? 'border-white ring-2 ring-white/20' 
                          : 'border-transparent hover:border-gray-600'
                      }`}
                    >
                      <img 
                        src={item.imageUrl} 
                        alt="History item" 
                        className="w-full h-full object-cover" 
                      />
                      <div className="absolute inset-0 bg-black/0 group-hover:bg-black/10 transition-colors" />
                    </button>
                  ))}
                </div>
              </div>
            )}
          </div>
        </div>
      </main>

      {/* Lightbox Overlay */}
      {isLightboxOpen && generatedImage && (
        <div 
          className="fixed inset-0 z-[100] flex items-center justify-center bg-black/95 backdrop-blur-md p-4 animate-in fade-in duration-200"
          onClick={() => setIsLightboxOpen(false)}
        >
          {/* Close Button */}
          <button 
            className="absolute top-6 right-6 text-gray-400 hover:text-white transition-colors bg-gray-900 rounded-full p-2 hover:bg-gray-800 border border-gray-800 z-50"
            onClick={(e) => {
              e.stopPropagation();
              setIsLightboxOpen(false);
            }}
          >
            <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={1.5} stroke="currentColor" className="w-8 h-8">
              <path strokeLinecap="round" strokeLinejoin="round" d="M6 18L18 6M6 6l12 12" />
            </svg>
          </button>

          <img 
            src={generatedImage} 
            alt="Full Resolution Result" 
            className="max-w-full max-h-full object-contain shadow-2xl rounded-sm border border-gray-800"
            onClick={(e) => e.stopPropagation()}
          />
        </div>
      )}
    </div>
  );
};

export default App;
